const [tab,setTab]=useState<Tab>("overview"),[items,setItems]=useState<Tx[]>([]),[ready,setReady]=useState(false),[show,setShow]=useState(false),[msg,setMsg]=useState(notice||""),[query,setQuery]=useState(""),[kindFilter,setKindFilter]=useState("all"),[currency,setCurrency]=useState(language==="en"?"USD":"IRR"),[saving,setSaving]=useState("500000"),[months,setMonths]=useState("12"),[theme,setTheme]=useState<"light"|"dark"|"auto">("light"),[showBalance,setShowBalance]=useState(true),[noticeOpen,setNoticeOpen]=useState(false),[spendCategory,setSpendCategory]=useState(""),[prefs,setPrefs]=useState<Preferences>(defaultPreferences); const viewItems=demoMode?demoTransactions:items; const viewCurrency=demoMode?"USD":currency;
const [form,setForm]=useState({title:"",amount:"",kind:"expense" as "income"|"expense",category:"عمومی",date:today(),note:"",recurring:false,frequency:"monthly" as "monthly"|"weekly"}); const [plan,setPlan]=useState<"free"|"pro">("free"); const [paywall,setPaywall]=useState(false); const [smsText,setSmsText]=useState(""); const [repeatItems,setRepeatItems]=useState<any[]>([]);
