const income=sum(viewItems,"income"),expense=sum(viewItems,"expense"),balance=income-expense,mi=sum(monthItems,"income"),me=sum(monthItems,"expense");const prevMonthDate=new Date();prevMonthDate.setMonth(prevMonthDate.getMonth()-1);const prevMonthItems=viewItems.filter(x=>x.date.slice(0,7)===prevMonthDate.toISOString().slice(0,7));const prevMonthExpense=sum(prevMonthItems,"expense");const monthCategoryTotals=Object.entries(monthItems.filter(x=>x.kind==="expense").reduce<Record<string,number>>((acc,x)=>{acc[x.category]=(acc[x.category]||0)+x.amount;return acc},{})).sort((a,b)=>b[1]-a[1]);
const top=Object.entries(viewItems.filter(x=>x.kind==="expense").reduce<Record<string,number>>((a,x)=>{a[x.category]=(a[x.category]||0)+x.amount;return a},{})).sort((a,b)=>b[1]-a[1])[0];const weekNow=new Date();weekNow.setHours(0,0,0,0);const weekStart=new Date(weekNow);weekStart.setDate(weekNow.getDate()-6);const priorWeekStart=new Date(weekStart);priorWeekStart.setDate(weekStart.getDate()-7);const weeklyExpense=viewItems.filter(x=>x.kind==="expense"&&new Date(x.date+"T12:00:00")>=weekStart&&new Date(x.date+"T12:00:00")<=weekNow).reduce((n,x)=>n+x.amount,0);const priorWeeklyExpense=viewItems.filter(x=>x.kind==="expense"&&new Date(x.date+"T12:00:00")>=priorWeekStart&&new Date(x.date+"T12:00:00")<weekStart).reduce((n,x)=>n+x.amount,0);const weeklyChange=priorWeeklyExpense?Math.round((weeklyExpense-priorWeeklyExpense)/priorWeeklyExpense*100):null;
